const Inner = ({ onMount }: { onMount: () => void }) => {
    useEffect(() => {
        onMount();
    }, []);
    return <div data-testid="inner">I'm only mounted once</div>;
};

const MyModal = ({
    open,
    onClose,
    children,
    disableCloseOnEscape,
